repo.harvests.py:
"""Harvest records."""


class Harvest:
    def __init__(self, field, kilos):
        self.field = field
        self.kilos = kilos

    def __repr__(self):
        return "Harvest(%r, %r)" % (self.field, self.kilos)


ROWS = [('lower', 20), ('lower', 29), ('upper', 21), ('upper', 33), ('river', 15), ('river', 30), ('lower', 10)]


def load_harvests():
    """Yield the stored harvests one at a time."""
    for field, kilos in ROWS:
        yield Harvest(field, kilos)

repo.podium.py:
"""Top harvests by kilos."""


def _take_largest(harvests):
    """Remove and return the harvest with the largest kilos."""
    best = max(harvests, key=lambda x: x.kilos)
    harvests.remove(best)
    return best


def podium(harvests, places=3):
    """Return the top `places` harvests by kilos, largest first. The caller's list is left as it was."""
    top = []
    while harvests and len(top) < places:
        top.append(_take_largest(harvests))
    return top


def report(harvests):
    """Return the podium values, the number of harvests and every kilos."""
    return {"podium": [x.kilos for x in podium(harvests)], "count": len(harvests), "all": [x.kilos for x in harvests]}


def describe_harvest(harvest):
    """Return a one-line description of a harvest."""
    return "%s: %s" % (harvest.field, harvest.kilos)
